theory = (
 H("A", "Arranging things for an open day", "Sắp xếp đồ đạc cho ngày hội trường")
 + P("A group of students are getting things ready for a college open day.", "Một nhóm sinh viên đang chuẩn bị cho ngày hội mở cửa của trường.")
 + T([
    ("<b>prop up</b> / <b>double up as</b>", "Ben needs something under or against the video camera to keep it in place; Anna says the bookcase can also be used as a support.", "Ben cần thứ gì kê để giữ máy quay; Anna nói giá sách có thể dùng luôn làm chỗ đỡ."),
    ("<b>sift through</b> / <b>pile up</b>", "Paul wants to look carefully through everything before it is thrown away; Kelly asks people to put their rubbish in a pile in the corner.", "Paul muốn lục xem kỹ mọi thứ trước khi vứt; Kelly nhờ mọi người dồn rác thành đống ở góc."),
    ("<b>space out</b> / <b>line up</b>", "The tables are too close and need more space between them, and should be made straight and neat (space out: see Unit 16).", "Bàn quá sát, cần giãn ra và xếp thẳng hàng cho gọn (space out: xem bài 16)."),
    ("<b>separate out</b> / <b>know</b> … <b>from</b>", "Paul suggests dividing the work by year group; Jake asks how he will tell first-year work apart from the rest.", "Paul đề nghị chia bài theo năm học; Jake hỏi làm sao phân biệt bài năm nhất với phần còn lại."),
    ("<b>separate off</b> / <b>round up</b>", "The work displays will be taken away from the rest and put in another room; Jake will find and gather more helpers.", "Các khu trưng bày bài làm sẽ được tách riêng sang phòng khác; Jake sẽ đi gom thêm người giúp."),
    ("<b>gather up</b> / <b>stack up</b> / <b>see about</b>", "Tim collects the brochures and puts them in one tall pile; Elodie will arrange an extra table.", "Tim gom tờ rơi lại và chồng thành một chồng; Elodie sẽ lo thêm một cái bàn."),
 ])
 + H("B", "Other verbs connected with organising and arranging things", "Các động từ khác về sắp xếp, tổ chức")
 + T([
    ("<b>hoard away</b>", "store a supply somewhere safe for later (bottles of water before hot weather)", "cất trữ để dùng sau (trữ nước trước đợt nóng)"),
    ("<b>fix up</b>", "(informal) arrange (a meeting with the local MP)", "(thân mật) sắp xếp (cuộc gặp với nghị sĩ địa phương)"),
    ("<b>fold up</b> / <b>do up</b>", "make a scarf smaller and neater; tie the present with a bow", "gấp gọn chiếc khăn; buộc quà bằng nơ"),
    ("<b>gear</b> … <b>towards</b>", "make a speech suitable mainly for parents rather than pupils", "soạn bài nói chủ yếu cho phụ huynh thay vì học sinh"),
    ("<b>rank among</b>", "have a place in a list ordered by quality (one of the best colleges)", "đứng trong một danh sách xếp hạng (một trong các trường tốt nhất)"),
 ])
 + NOTE("<b>Exercise 25.1 answers</b>: you can <b>round up</b> sheep or cattle, and also round up a bill to the next whole number (Unit 26); you might <b>prop</b> your head <b>up</b> with a cushion; <b>pile up</b> is close to <b>stack up</b>; <b>sift through</b> = look for what matters among less important things. <b>up</b> means upward in <b>prop up</b>, <b>pile up</b>, <b>stack up</b>, but ‘together’ in <b>gather up</b>, <b>round up</b>, <b>line up</b>.",
        "<b>Đáp án bài 25.1</b>: có thể <b>round up</b> cừu, bò, và cả làm tròn hóa đơn lên số chẵn (bài 26); có thể <b>prop</b> đầu <b>up</b> bằng gối; <b>pile up</b> gần nghĩa <b>stack up</b>; <b>sift through</b> = tìm thứ quan trọng giữa những thứ kém quan trọng. <b>up</b> nghĩa là ‘lên trên’ trong <b>prop up</b>, <b>pile up</b>, <b>stack up</b>, nhưng là ‘gom lại’ trong <b>gather up</b>, <b>round up</b>, <b>line up</b>.")
)
